static void dump(HANDLE p, uintptr_t base, const char *where){unsigned char t[64]={0},a[64]={0};SIZE_T n=0;ReadProcessMemory(p,(void*)(base+0x4000),t,64,&n);ReadProcessMemory(p,(void*)(base+0x4040),a,64,&n);printf("%s TARGET_HEX:",where);for(int i=0;i<64;i++)printf("%02x",t[i]);puts("");printf("%s TARGET_ASCII:",where);for(int i=0;i<64;i++)putchar(t[i]>=32&&t[i]<127?t[i]:'.');puts("");printf("%s ALPHABET_HEX:",where);for(int i=0;i<64;i++)printf("%02x",a[i]);puts("");printf("%s ALPHABET_ASCII:",where);for(int i=0;i<64;i++)putchar(a[i]>=32&&a[i]<127?a[i]:'.');puts("");}
static void disable_dr0(HANDLE th){CONTEXT x={0};x.ContextFlags=CONTEXT_DEBUG_REGISTERS;if(GetThreadContext(th,&x)){x.Dr7 &= ~1ULL;SetThreadContext(th,&x);}}
int main(int argc,char**argv){if(argc<3){puts("usage: dumpmain3.exe target.exe stdin-file");return 2;}SECURITY_ATTRIBUTES sa={sizeof(sa),0,TRUE};HANDLE hin=CreateFileA(argv[2],GENERIC_READ,FILE_SHARE_READ,&sa,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,0);if(hin==INVALID_HANDLE_VALUE){printf("stdin open error=%lu\n",GetLastError());return 3;}STARTUPINFOA si={0};PROCESS_INFORMATION pi={0};si.cb=sizeof(si);si.dwFlags=STARTF_USESTDHANDLES;si.hStdInput=hin;si.hStdOutput=GetStdHandle(STD_OUTPUT_HANDLE);si.hStdError=GetStdHandle(STD_ERROR_HANDLE);char cmd[4096];snprintf(cmd,sizeof(cmd),"/"%s/"",argv[1]);if(!CreateProcessA(argv[1],cmd,0,0,TRUE,DEBUG_ONLY_THIS_PROCESS|CREATE_NO_WINDOW,0,0,&si,&pi)){printf("CreateProcess error=%lu\n",GetLastError());return 4;}CloseHandle(hin);uintptr_t base=0;int seenOep=0,seenMain=0,done=0,n=0;while(!done&&n++<1000){DEBUG_EVENT e;if(!WaitForDebugEvent(&e,5000)){printf("WaitForDebugEvent error=%lu\n",GetLastError());break;}DWORD c=DBG_CONTINUE;if(e.dwDebugEventCode==CREATE_PROCESS_DEBUG_EVENT){base=(uintptr_t)e.u.CreateProcessInfo.lpBaseOfImage;printf("CREATE_PROCESS base=%p entry=%p OEP=%p main=%p thread=%lu\n",(void*)base,e.u.CreateProcessInfo.lpStartAddress,(void*)(base+0x1f20),(void*)(base+0x1000),e.dwThreadId);if(e.u.CreateProcessInfo.hFile)CloseHandle(e.u.CreateProcessInfo.hFile);CONTEXT x={0};x.ContextFlags=CONTEXT_DEBUG_REGISTERS;if(GetThreadContext(e.u.CreateProcessInfo.hThread,&x)){x.Dr0=base+0x1f20;x.Dr1=base+0x1000;x.Dr7=0x5;BOOL ok=SetThreadContext(e.u.CreateProcessInfo.hThread,&x);printf("SET_HARDWARE_BREAKPOINTS oep=%p main=%p set=%d dr7=0x%llx\n",(void*)x.Dr0,(void*)x.Dr1,ok,(unsigned long long)x.Dr7);}else printf("GetThreadContext failed=%lu\n",GetLastError());}else if(e.dwDebugEventCode==LOAD_DLL_DEBUG_EVENT){if(e.u.LoadDll.hFile)CloseHandle(e.u.LoadDll.hFile);}else if(e.dwDebugEventCode==EXCEPTION_DEBUG_EVENT){DWORD code=e.u.Exception.ExceptionRecord.ExceptionCode;uintptr_t a=(uintptr_t)e.u.Exception.ExceptionRecord.ExceptionAddress;printf("EXCEPTION code=0x%08lx address=%p chance=%lu\n",code,(void*)a,e.u.Exception.dwFirstChance);if(code==EXCEPTION_SINGLE_STEP&&a==base+0x1f20&&!seenOep){seenOep=1;dump(pi.hProcess,base,"AT_OEP");disable_dr0(pi.hThread);printf("DISABLED_DR0_AFTER_OEP\n");}else if(code==EXCEPTION_SINGLE_STEP&&a==base+0x1000&&!seenMain){seenMain=1;dump(pi.hProcess,base,"AT_MAIN");done=1;TerminateProcess(pi.hProcess,0);}else if(code==EXCEPTION_BREAKPOINT||code==EXCEPTION_SINGLE_STEP)c=DBG_CONTINUE;else c=DBG_EXCEPTION_NOT_HANDLED;}else if(e.dwDebugEventCode==EXIT_PROCESS_DEBUG_EVENT){printf("EXIT_PROCESS code=0x%08lx\n",e.u.ExitProcess.dwExitCode);done=1;}if(!ContinueDebugEvent(e.dwProcessId,e.dwThreadId,c)){printf("ContinueDebugEvent failed=%lu\n",GetLastError());break;}}DWORD ec=0;GetExitCodeProcess(pi.hProcess,&ec);printf("debug_exit=%lu events=%d done=%d seenOep=%d seenMain=%d\n",ec,n,done,seenOep,seenMain);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return 0;}
